var DecisionV2Utils = Class.create();
DecisionV2Utils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	//カスタムDecisionテーブルの情報を参照
    getDecisionResults: function() {

		var params = JSON.parse(this.getParameter("inputs"));
        var inputs = {
			instance_type: params.instance_type
		};

		var dt = new sn_dt.DecisionTableAPI(); 
       // var dtSysId = 'fe3fc51d0f1b3a147409c9c530d1b215'; // カスタムDecisionテーブルsys_id
		var dtSysId = '51b35a90c3723010a9f5e548fa40ddb2';

		//var response = dt.getDecision(dtSysId, inputs);
		//var response = dt.getAnswers(dtSysId);
		var response = dt.getAll(dtSysId);
		gs.info('respoinputsnse1' + JSON.stringify(inputs));
		gs.info('response' + JSON.stringify(response));
        return JSON.stringify(response);

        /*var output = {};
        if (response  && response.result_elements) {
			output.u_pattenrn_1 = response.result_elements.u_pattenrn_1.getDisplayValue();
			output.step2_1 = response.result_elements.step2_1.getDisplayValue();
            output.success = true;
        } else {
            output.success = false;
            output.message = '決策表に一致するルールが存在しません';
        }

        return JSON.stringify(output);*/

        },

    getEmployeeInfo: function() {
        var userGr = new GlideRecord('sys_user');
        var name = this.getParameter('user');
        userGr.get(name);

        var configuration = {};	
        configuration.name = userGr.name + ''; //氏名
        configuration.email = userGr.email + ''; //メールアドレス

        return JSON.stringify(configuration);
    },
	//decisionのsys_IDを取得
    getSysId: function() {
        var name = this.getParameter('name');
        var gr = new GlideRecord('sys_decision');
        gr.addQuery('name', name);
        gr.query();

        if (gr.next()) {
            return gr.getValue('sys_id');
        }
        return 'No Decision Table found with name: ' + name;
    },


    type: 'DecisionV2Utils'
});
